let expScreen='map', expZoom=1;
const expPins=[[28,75],[18,46],[49,57],[45,27],[66,12],[82,46],[81,83]];
function playHub(){app.innerHTML=`<h2 class="world-title">Choose your adventure</h2><button class="mode-panel" onclick="go('Battle')"><img src="data:image/webp;base64," alt="Lion and tiger"><div><h2>Wild Battle</h2><p>Build your deck and challenge opponents.</p><small>Best of five · Earn coins</small></div></button><button class="mode-panel" onclick="expScreen='map';go('Expedition')"><img src="data:image/webp;base64," alt="Wild landscape"><div><h2>Wild Expeditions</h2><p>Explore the world and conquer its habitats.</p><small>7 regions · 70 stages · 7 bosses</small></div></button>`;}
function expContinue(){expeditionRegion=Math.min(6,Math.floor(expeditionProgress().cleared/10));expScreen='stages';go('Expedition');}
function expCount(r){return Math.max(0,Math.min(10,expeditionProgress().cleared-r*10));}
function expSelect(r){expeditionRegion=r;render();}
function expEnter(){if(expeditionRegion*10<=expeditionProgress().cleared){expScreen='stages';render();}}
function expScale(d){expZoom=Math.max(1,Math.min(2.5,expZoom+d));const el=document.querySelector('.world-canvas');if(el){el.style.width=expZoom*100+'%';}}
function expCampaign(){const p=expeditionProgress(),r=expeditionRegion,[h,emoji]=expeditionRegions[r],count=expCount(r),open=r*10<=p.cleared,boss=species[expeditionTeam(r,10)[5].id];if(expScreen==='map'){app.innerHTML=`<button onclick="go('Play')">← Play</button><h2 class="world-title">The Wild World</h2><p>${p.cleared}/70 stages cleared</p><progress max="70" value="${p.cleared}"></progress><div class="world-controls"><button onclick="expScale(-.25)">−</button><button onclick="expScale(.25)">+</button></div><div class="world-scroll"><div class="world-canvas" style="width:${expZoom*100}%"><svg viewBox="0 0 100 100" preserveAspectRatio="none" class="world-path"><polyline points="${expPins.map(v=>v.join(',')).join(' ')}"/><polyline class="world-active" points="${expPins.slice(0,Math.min(7,Math.floor(p.cleared/10)+1)).map(v=>v.join(',')).join(' ')}"/></svg>${expeditionRegions.map(([name,icon],i)=>`<button class="world-pin ${i===r?'selected':''} ${i*10>p.cleared?'locked':''}" style="left:${expPins[i][0]}%;top:${expPins[i][1]}%" onclick="expSelect(${i})"><span>${icon}</span>${name}<small>${i*10>p.cleared?'🔒':expCount(i)+'/10'}</small></button>`).join('')}</div></div><div class="panel"><h3>${emoji} ${h}</h3><p>${count}/10 stages · 1 boss</p><button class="gold" ${open?'':'disabled'} onclick="expEnter()">${open?'Enter region':'Locked'}</button></div>`;return;}app.innerHTML=`<button onclick="expScreen='map';render()">← World map</button><div class="biome-banner">${r===0?'<img src="data:image/webp;base64," alt="Savanna">':animalArtwork(boss)}</div><h2 class="world-title">${h} Expedition</h2><p>${count}/10 stages completed</p><progress max="10" value="${count}"></progress><div class="stage-grid">${Array.from({length:10},(_,i)=>{let s=i+1,n=r*10+s;return `<button class="${n===p.cleared+1?'gold':''} ${n<=p.cleared?'cleared':''}" ${n>p.cleared+1||state.deck.length!==6?'disabled':''} onclick="expeditionStart(${r},${s})"><b>${s===10?'👑':s}</b><small>${n<=p.cleared?'★':n===p.cleared+1?'⚔':'🔒'}</small></button>`}).join('')}</div>${state.deck.length!==6?'<p>Build a six-card deck first.</p>':''}<div class="panel boss-preview"><div class="boss-art">${animalArtwork(boss)}</div><div><small>REGION BOSS</small><h3>${boss.name}</h3><p>${expeditionReward(r,10)} coins + guaranteed animal card</p></div></div><div class="panel">Region rewards · ${Array.from({length:10},(_,i)=>expeditionReward(r,i+1)).reduce((a,b)=>a+b,0)} coins · 1 guaranteed card</div>`;}

function worldHome(){const p=expeditionProgress(),r=Math.min(6,Math.floor(p.cleared/10));app.innerHTML=`<div class="wd-home-art" role="img" aria-label="Lion overlooking the savanna"></div><section class="wd-home-panel"><small>SEASON 01 · FOUNDATION</small><h2>Rule the wild.</h2><p>Collect species, build your deck and conquer the world's habitats.</p><div class="wd-home-actions"><button class="gold" onclick="go('Play')">⚔ Play</button><button onclick="expContinue()">Continue Expedition<small>${expeditionRegions[r][0]} · ${p.cleared===70?'Complete':'Stage '+(p.cleared%10+1)+' / 10'}</small></button></div></section><div class="wd-home-stats"><button onclick="go('Collection')">♧<small>Species</small><b>${new Set(state.cards.map(c=>c.id)).size} / ${species.length}</b></button><button onclick="go('Deck')">▱<small>Deck</small><b>${state.deck.length} / 6</b></button><button onclick="expScreen='map';go('Expedition')">⚑<small>Expeditions</small><b>${p.cleared} / 70</b></button></div><p class="muted wd-build">V1.6.2 · Visual Overhaul</p>`;}
